"""Exact local transposition bounds used with Orevkov's degree-six ledger."""
from itertools import combinations
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
identity=tuple(range(6))
transpositions=[]
for a,b in combinations(range(6),2):
    p=list(identity);p[a],p[b]=p[b],p[a];transpositions.append(tuple(p))


def compose(a,b):return tuple(a[b[i]] for i in range(6))
def mul(*ps):
    result=identity
    for p in ps:result=compose(result,p)
    return result
def power(p,n):return mul(*([p]*n))


def excess(ps):
    # The local orbits of the subgroup generated by the branch meridians.
    neighbors=[set() for _ in range(6)]
    edges=[]
    for p in ps:
        moved=[i for i in range(6) if p[i]!=i]
        edges.append(moved);a,b=moved;neighbors[a].add(b);neighbors[b].add(a)
    sizes=[]
    for a,b in edges:
        reached={a};todo=[a]
        while todo:
            i=todo.pop()
            for j in neighbors[i]-reached:reached.add(j);todo.append(j)
        sizes.append(len(reached))
    return sum(size-2 for size in sizes)


def main():
    first=transpositions[0];cusps=[];nodes=[];a5=[]
    for second in transpositions:
        if mul(first,second,first)==mul(second,first,second):
            # One normalization branch at an ordinary cusp, so count the
            # common orbit once, rather than once for each fiber meridian.
            cusps.append(excess([first,second])//2)
        if mul(first,second)==mul(second,first):nodes.append(excess([first,second]))
        if power(mul(first,second),3)==power(mul(second,first),3):a5.append(excess([first,second]))
    assert max(cusps)==1 and set(nodes)=={0} and max(a5)==2
    required=6-1-2
    assert required==3 and max(cusps)<required
    result={'sheets':6,'dicritical_moved_cost':2,'required_Orevkov_excess':required,
            'ordinary_cusp_maximum':max(cusps),'node_maximum':max(nodes),
            'A5_two_branch_maximum':max(a5),
            'assumption':'The complete affine dicritical ledger consists of one (e,f)=(2,1) row; no additional missing unramified row is assumed.',
            'A2_plus_11_nodes_excluded_under_complete_one_row_ledger':True,
            'A2_plus_A5_plus_8_nodes_not_excluded':max(cusps)+max(a5)==required,
            'boundary':'Uses the finite-normalization local orbit interpretation and residue degree one from the canonical F2 degree-six Stein proof; no full complement-group assertion.'}
    (ROOT/'local-excess.json').write_text(json.dumps(result,indent=2)+'\n')
    print('PASS CONDITIONAL LOCAL EXCESS: with complete one-row ledger, A2+11A1 at most 1 < required 3')


if __name__=='__main__':main()
